"""Сервис складского учёта: приход, расход, перемещение, инвентаризация.

Любая операция, меняющая остатки, пишет событие в журнал
(:class:`~warehouse.events.EventLog`). Операция либо выполняется целиком,
либо не меняет ничего — ни остатков, ни журнала.
"""

from __future__ import annotations

import logging
from dataclasses import replace
from datetime import timedelta
from typing import Iterable

from .clock import Clock, SystemClock
from .errors import (
    DuplicateReservationError,
    DuplicateSkuError,
    InsufficientStockError,
    InvalidQuantityError,
    ReservationExpiredError,
    ReservationNotFoundError,
    ReservationStateError,
    UnknownSkuError,
    ValidationError,
)
from .events import EventLog, format_timestamp
from .models import Availability, Reservation, ReservationLine, ReservationStatus, Sku, StockLevel
from .reservations import (
    DEFAULT_RESERVATION_TTL,
    MAX_RESERVATION_LIFETIME,
    normalize_lines,
    validate_ttl,
)
from .storage import InMemoryStore

logger = logging.getLogger(__name__)


class Inventory:
    """Остатки товаров по складам."""

    def __init__(
        self,
        store: InMemoryStore | None = None,
        clock: Clock | None = None,
        log: EventLog | None = None,
    ) -> None:
        self._store = store if store is not None else InMemoryStore()
        self._clock = clock if clock is not None else SystemClock()
        self._log = log if log is not None else EventLog()
        self._reservations: dict[str, Reservation] = {}
        # поколение резерва по заказу: новый резерв на тот же заказ — другой резерв
        self._generation: dict[str, int] = {}
        self._swept: set[tuple[str, int]] = set()
        # истёкшие, но не отмеченные резервы, вытесненные новым резервом того же заказа
        self._superseded: list[tuple[int, Reservation]] = []

    @property
    def store(self) -> InMemoryStore:
        return self._store

    @property
    def clock(self) -> Clock:
        return self._clock

    @property
    def log(self) -> EventLog:
        return self._log

    # --- справочник ---------------------------------------------------------

    def register_sku(self, code: str, name: str, unit: str = "pcs") -> Sku:
        _validate_code(code, "SKU code")
        if self._store.has_sku(code):
            raise DuplicateSkuError(code)
        sku = Sku(code=code, name=name, unit=unit)
        self._store.add_sku(sku)
        logger.info("registered SKU %s", code)
        return sku

    def get_sku(self, code: str) -> Sku:
        sku = self._store.get_sku(code)
        if sku is None:
            raise UnknownSkuError(code)
        return sku

    # --- запросы ------------------------------------------------------------

    def on_hand(self, warehouse: str, sku: str) -> int:
        """Физический остаток SKU на складе."""
        self._require_sku(sku)
        return self._store.get_qty(warehouse, sku)

    def stock_levels(self, warehouse: str | None = None) -> list[StockLevel]:
        """Ненулевые физические остатки, отсортированные по складу и SKU."""
        return [
            StockLevel(warehouse=wh, sku=sku, on_hand=qty)
            for wh, sku, qty in self._store.positions()
            if warehouse is None or wh == warehouse
        ]

    # --- операции -----------------------------------------------------------

    def receive(self, warehouse: str, sku: str, qty: int, ref: str | None = None) -> int:
        """Приход товара. Возвращает новый физический остаток."""
        self._check_position(warehouse, sku)
        _validate_qty(qty)
        _validate_ref(ref)
        new_qty = self._store.get_qty(warehouse, sku) + qty
        self._store.set_qty(warehouse, sku, new_qty)
        self._log.append(self._clock.now(), "RECEIVE", wh=warehouse, sku=sku, qty=qty, ref=ref)
        logger.info("received %s x%d at %s", sku, qty, warehouse)
        return new_qty

    def issue(self, warehouse: str, sku: str, qty: int, ref: str | None = None) -> int:
        """Расход (отгрузка, списание). Возвращает новый физический остаток."""
        self._check_position(warehouse, sku)
        _validate_qty(qty)
        _validate_ref(ref)
        current = self._store.get_qty(warehouse, sku)
        free = self._available(warehouse, sku)
        if qty > free:
            raise InsufficientStockError(warehouse, sku, qty, free)
        self._store.set_qty(warehouse, sku, current - qty)
        self._log.append(self._clock.now(), "ISSUE", wh=warehouse, sku=sku, qty=qty, ref=ref)
        logger.info("issued %s x%d from %s", sku, qty, warehouse)
        return current - qty

    def transfer(
        self, source: str, target: str, sku: str, qty: int, ref: str | None = None
    ) -> None:
        """Перемещение между складами одним событием ``TRANSFER``.

        Для склада-источника это обычный расход: проверки те же, что у :meth:`issue`.
        """
        self._check_position(source, sku)
        _validate_code(target, "warehouse")
        if source == target:
            raise ValidationError("source and target warehouses must differ")
        _validate_qty(qty)
        _validate_ref(ref)
        current = self._store.get_qty(source, sku)
        free = self._available(source, sku)
        if qty > free:
            raise InsufficientStockError(source, sku, qty, free)
        self._store.set_qty(source, sku, current - qty)
        self._store.set_qty(target, sku, self._store.get_qty(target, sku) + qty)
        self._log.append(
            self._clock.now(), "TRANSFER", src=source, dst=target, sku=sku, qty=qty, ref=ref
        )
        logger.info("moved %s x%d %s -> %s", sku, qty, source, target)

    def adjust(self, warehouse: str, sku: str, counted: int, reason: str) -> int:
        """Инвентаризация: фиксирует фактически посчитанный остаток.

        Это факт, а не запрос, поэтому никаких проверок достаточности нет.
        В журнал пишется разница ``delta`` (может быть отрицательной).
        """
        self._check_position(warehouse, sku)
        if isinstance(counted, bool) or not isinstance(counted, int) or counted < 0:
            raise ValidationError(f"counted quantity must be a non-negative integer, got {counted!r}")
        _validate_code(reason, "reason")
        current = self._store.get_qty(warehouse, sku)
        self._store.set_qty(warehouse, sku, counted)
        self._log.append(
            self._clock.now(), "ADJUST", wh=warehouse, sku=sku, delta=counted - current, reason=reason
        )
        logger.warning("stock of %s at %s adjusted %d -> %d", sku, warehouse, current, counted)
        return counted

    # --- резервы ------------------------------------------------------------
    def available(self, warehouse: str, sku: str) -> int:
        """Физический остаток минус активные резервы (не меньше 0)."""
        self._check_position(warehouse, sku)
        return self._available(warehouse, sku)

    def reserved(self, warehouse: str, sku: str) -> int:
        """Сумма активных резервов по позиции."""
        self._check_position(warehouse, sku)
        return self._reserved(warehouse, sku)

    def reserve(
        self,
        order_id: str,
        lines: Iterable[tuple[str, str, int] | ReservationLine],
        ttl: timedelta | None = None,
    ) -> Reservation:
        """Резервирует товар под заказ сразу по всем строкам."""
        _validate_code(order_id, "order_id")
        ttl = DEFAULT_RESERVATION_TTL if ttl is None else validate_ttl(ttl)
        if ttl > MAX_RESERVATION_LIFETIME:
            raise ValidationError(f"ttl must not exceed {MAX_RESERVATION_LIFETIME}, got {ttl!r}")
        norm = normalize_lines(lines)
        if not norm:
            raise ValidationError("reservation must have at least one line")
        for line in norm:
            self._check_position(line.warehouse, line.sku)
            _validate_qty(line.qty)
        existing = self._snapshot(order_id)
        if existing is not None and existing.status is ReservationStatus.CONFIRMED:
            raise DuplicateReservationError(order_id)
        replaced = existing is not None and existing.status is ReservationStatus.ACTIVE
        for position, total in _totals(norm).items():
            free = self._available(*position, exclude=order_id if replaced else None)
            if total > free:
                raise InsufficientStockError(position[0], position[1], total, free)
        now = self._clock.now()
        if replaced:
            self._log.append(now, "RESERVE_CANCEL", order=order_id)
        elif existing is not None and existing.status is ReservationStatus.EXPIRED:
            old_gen = self._generation.get(order_id, 0)
            if (order_id, old_gen) not in self._swept:
                self._superseded.append((old_gen, existing))
        record = Reservation(order_id, norm, now, now + ttl, ReservationStatus.ACTIVE)
        self._reservations[order_id] = record
        self._generation[order_id] = self._generation.get(order_id, 0) + 1
        expires = format_timestamp(record.expires_at)
        for line in norm:
            self._log.append(
                now, "RESERVE", order=order_id, wh=line.warehouse, sku=line.sku,
                qty=line.qty, expires=expires,
            )
        logger.info("reserved order %s (%d lines)", order_id, len(norm))
        return record

    def confirm(self, order_id: str) -> Reservation:
        """Превращает активный резерв в отгрузку."""
        record = self._require_active(order_id)
        for (wh, sku), total in _totals(record.lines).items():
            current = self._store.get_qty(wh, sku)
            if total > current:
                raise InsufficientStockError(wh, sku, total, current)
        now = self._clock.now()
        for line in record.lines:
            current = self._store.get_qty(line.warehouse, line.sku)
            self._store.set_qty(line.warehouse, line.sku, current - line.qty)
            self._log.append(
                now, "ISSUE", wh=line.warehouse, sku=line.sku, qty=line.qty, ref=order_id
            )
        self._log.append(now, "RESERVE_CONFIRM", order=order_id)
        record = replace(record, status=ReservationStatus.CONFIRMED)
        self._reservations[order_id] = record
        logger.info("confirmed order %s", order_id)
        return record

    def cancel(self, order_id: str) -> Reservation:
        """Освобождает резерв. Повторная отмена и отмена истёкшего — без эффекта."""
        snap = self._require_reservation(order_id)
        if snap.status is ReservationStatus.CONFIRMED:
            now = self._clock.now()
            for line in snap.lines:
                current = self._store.get_qty(line.warehouse, line.sku)
                self._store.set_qty(line.warehouse, line.sku, current + line.qty)
                self._log.append(
                    now, "RECEIVE", wh=line.warehouse, sku=line.sku, qty=line.qty, ref=order_id
                )
            record = replace(snap, status=ReservationStatus.CANCELLED)
            self._reservations[order_id] = record
            self._log.append(now, "RESERVE_CANCEL", order=order_id)
            logger.info("refunded order %s", order_id)
            return record
        if snap.status is not ReservationStatus.ACTIVE:
            return snap
        record = replace(snap, status=ReservationStatus.CANCELLED)
        self._reservations[order_id] = record
        self._log.append(self._clock.now(), "RESERVE_CANCEL", order=order_id)
        logger.info("cancelled order %s", order_id)
        return record

    def extend(self, order_id: str, ttl: timedelta) -> Reservation:
        """Переносит срок активного резерва на ``now + ttl``, но не сокращает его."""
        validate_ttl(ttl)
        record = self._require_active(order_id)
        now = self._clock.now()
        new_expires = min(now + ttl, record.created_at + MAX_RESERVATION_LIFETIME)
        if new_expires <= record.expires_at:
            return record
        record = replace(record, expires_at=new_expires)
        self._reservations[order_id] = record
        self._log.append(
            now, "RESERVE_EXTEND", order=order_id, expires=format_timestamp(new_expires)
        )
        return record

    def get_reservation(self, order_id: str) -> Reservation:
        return self._require_reservation(order_id)

    def reservations(self, status: ReservationStatus | None = None) -> list[Reservation]:
        """Снимки резервов (по одному на заказ), по ``created_at`` и ``order_id``."""
        snaps = [self._snapshot(order_id) for order_id in self._reservations]
        result = [s for s in snaps if s is not None and (status is None or s.status is status)]
        result.sort(key=lambda r: (r.created_at, r.order_id))
        return result

    def availability(self, warehouse: str | None = None) -> list[Availability]:
        """Остаток, резерв и доступное количество по каждой задействованной позиции."""
        positions = {(lv.warehouse, lv.sku) for lv in self.stock_levels(warehouse)}
        for record in self._reservations.values():
            for line in record.lines:
                if warehouse is None or line.warehouse == warehouse:
                    positions.add((line.warehouse, line.sku))
        result = []
        for wh, sku in sorted(positions):
            on_hand = self._store.get_qty(wh, sku)
            reserved = self._reserved(wh, sku)
            if on_hand or reserved:
                result.append(Availability(wh, sku, on_hand, reserved, self._available(wh, sku)))
        return result

    def sweep_expired(self) -> list[str]:
        """Пишет ``RESERVE_EXPIRE`` по истёкшим резервам, о которых ещё не писали."""
        now = self._clock.now()
        pending = list(self._superseded)
        for order_id in self._reservations:
            snap = self._snapshot(order_id)
            gen = self._generation.get(order_id, 0)
            if (
                snap is not None
                and snap.status is ReservationStatus.EXPIRED
                and (order_id, gen) not in self._swept
            ):
                pending.append((gen, snap))
        pending.sort(key=lambda item: (item[1].expires_at, item[1].order_id))
        for gen, record in pending:
            self._swept.add((record.order_id, gen))
            self._log.append(
                now, "RESERVE_EXPIRE", order=record.order_id,
                expires=format_timestamp(record.expires_at),
            )
        self._superseded.clear()
        return [record.order_id for _, record in pending]

    # --- служебное ----------------------------------------------------------
    def _snapshot(self, order_id: str) -> Reservation | None:
        record = self._reservations.get(order_id)
        if (
            record is not None
            and record.status is ReservationStatus.ACTIVE
            and self._clock.now() >= record.expires_at
        ):
            return replace(record, status=ReservationStatus.EXPIRED)
        return record

    def _require_reservation(self, order_id: str) -> Reservation:
        snap = self._snapshot(order_id) if isinstance(order_id, str) else None
        if snap is None:
            raise ReservationNotFoundError(order_id)
        return snap

    def _require_active(self, order_id: str) -> Reservation:
        snap = self._require_reservation(order_id)
        if snap.status is ReservationStatus.EXPIRED:
            raise ReservationExpiredError(order_id)
        if snap.status is not ReservationStatus.ACTIVE:
            raise ReservationStateError(order_id, snap.status)
        return snap

    def _reserved(self, warehouse: str, sku: str, exclude: str | None = None) -> int:
        now = self._clock.now()
        return sum(
            line.qty
            for record in self._reservations.values()
            if record.status is ReservationStatus.ACTIVE and now < record.expires_at
            and record.order_id != exclude
            for line in record.lines
            if line.warehouse == warehouse and line.sku == sku
        )

    def _available(self, warehouse: str, sku: str) -> int:
        return max(0, self._store.get_qty(warehouse, sku) - self._reserved(warehouse, sku))


    def _require_sku(self, sku: str) -> None:
        if not self._store.has_sku(sku):
            raise UnknownSkuError(sku)

    def _check_position(self, warehouse: str, sku: str) -> None:
        _validate_code(warehouse, "warehouse")
        self._require_sku(sku)


def _validate_code(value: object, what: str) -> None:
    """Коды складов/SKU/ссылок попадают в журнал, поэтому без пробелов."""
    if not isinstance(value, str) or not value or any(ch.isspace() for ch in value) or "=" in value:
        raise ValidationError(f"{what} must be a non-empty string without spaces, got {value!r}")


def _validate_ref(ref: object) -> None:
    if ref is not None:
        _validate_code(ref, "ref")


def _validate_qty(qty: object) -> None:
    if isinstance(qty, bool) or not isinstance(qty, int) or qty <= 0:
        raise InvalidQuantityError(qty)


def _totals(lines: Iterable[ReservationLine]) -> dict[tuple[str, str], int]:
    totals: dict[tuple[str, str], int] = {}
    for line in lines:
        key = (line.warehouse, line.sku)
        totals[key] = totals.get(key, 0) + line.qty
    return totals
